<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';require_once __DIR__.'/lib/DataFormApp.php';$user=cal_auth_require('editor');$c=df_config();$pdo=df_pdo();$dfs=(array)($c['dataforms']??[]);$msg='';$err='';
$entities=['categories'=>['title'=>'Kategorien','fields'=>['name'=>'Bezeichnung']],'places'=>['title'=>'Orte','fields'=>['name'=>'Name','street'=>'Straße','postal_code'=>'PLZ','city'=>'Stadt','room'=>'Raum','description'=>'Beschreibung']],'resources'=>['title'=>'Ressourcen','fields'=>['name'=>'Name']],'persons'=>['title'=>'Personen','fields'=>['display_name'=>'Name','email'=>'E-Mail']]];
$entity=(string)($_GET['entity']??'categories');if(!isset($entities[$entity]))$entity='categories';$formId=(int)($dfs[$entity]??0);if($formId<1){$err='DataForm für '.$entity.' fehlt.';}
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['user_action'])){cal_auth_require('admin');cal_auth_upsert($_POST);$msg='Benutzer gespeichert.';}else{if($formId<1)throw new RuntimeException('DataForm fehlt.');$fields=df_fields($pdo,$formId);$id=max(0,(int)($_POST['record_id']??0));if((string)($_POST['action']??'save')==='delete'){if($id<1)throw new RuntimeException('Datensatz fehlt.');$old=df_find_record($pdo,$formId,$id,$fields);if(!$old)throw new RuntimeException('Datensatz nicht gefunden.');$d=(array)$old['data'];if(array_key_exists('activ',$d)){$d['activ']='0';df_write_record($pdo,$formId,$fields,$d,$id);}else df_delete_record($pdo,$formId,$id);$msg='Datensatz deaktiviert/gelöscht.';}else{$d=$id>0?(array)(df_find_record($pdo,$formId,$id,$fields)['data']??[]):[];foreach($entities[$entity]['fields'] as $name=>$label)$d[$name]=trim((string)($_POST[$name]??''));if(isset($d['activ'])||array_key_exists('activ',array_column($fields,null,'name')))$d['activ']=!empty($_POST['activ'])?'1':'0';if(isset($d['created_at'])&&$id<1)$d['created_at']=date('Y-m-d H:i:s');if(isset($d['updated_at']))$d['updated_at']=date('Y-m-d H:i:s');df_write_record($pdo,$formId,$fields,$d,$id?:null);$msg='Stammdatum gespeichert.';}}}}catch(Throwable $e){$err=$e->getMessage();}
$rows=[];$fields=[];$editId=max(0,(int)($_GET['edit']??0));$editData=[];if($formId>0){$fields=df_fields($pdo,$formId);$rows=df_raw_records($pdo,$formId,$fields);if($editId>0){$er=df_find_record($pdo,$formId,$editId,$fields);if($er)$editData=(array)$er['data'];}}?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>easyITCalendar Verwaltung</title><style>body{font:15px system-ui;margin:0;background:#eef3f8;color:#16283a}header{display:flex;gap:1rem;align-items:center;padding:.8rem 1rem;background:#12365e;color:#fff}header a{color:#fff}.wrap{max-width:1200px;margin:1rem auto;padding:0 1rem}.tabs{display:flex;flex-wrap:wrap;gap:.4rem;margin-bottom:1rem}.tabs a{padding:.55rem .8rem;background:#fff;border:1px solid #bcc9d6;border-radius:6px;text-decoration:none;color:#12365e}.card{background:#fff;border:1px solid #ccd6e1;border-radius:10px;padding:1rem;margin-bottom:1rem}label{display:grid;gap:.25rem;margin:.5rem 0;font-weight:700}input,textarea,select{padding:.55rem;border:1px solid #adb9c5;border-radius:5px;font:inherit}button{padding:.55rem .8rem;border:0;border-radius:5px;background:#0b5ca5;color:#fff;font-weight:700}.danger{background:#a33131}table{width:100%;border-collapse:collapse}th,td{padding:.45rem;border-bottom:1px solid #e0e6ec;text-align:left}.ok{color:#176b38}.err{color:#a11}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:.6rem}</style></head><body><header><strong>easyITCalendar – Setup / Stammdaten</strong><a href="index.php">Kalender</a><span style="margin-left:auto"><?=htmlspecialchars((string)$user['username'])?> (<?=htmlspecialchars((string)$user['role'])?>)</span><a href="logout.php">Abmelden</a></header><main class="wrap"><?php if($msg):?><p class="ok"><?=htmlspecialchars($msg)?></p><?php endif;?><?php if($err):?><p class="err"><?=htmlspecialchars($err)?></p><?php endif;?><nav class="tabs"><?php foreach($entities as $k=>$def):?><a href="?entity=<?=$k?>"><?=htmlspecialchars($def['title'])?></a><?php endforeach;?><?php if(cal_auth_can('admin')):?><a href="#users">Benutzer</a><?php endif;?></nav><section class="card"><h2><?=htmlspecialchars($entities[$entity]['title'])?></h2><form method="post"><input type="hidden" name="record_id" value="<?=$editId?>"><div class="grid"><?php foreach($entities[$entity]['fields'] as $name=>$label):?><label><?=htmlspecialchars($label)?><?php if($name==='description'):?><textarea name="<?=$name?>"><?=htmlspecialchars((string)($editData[$name]??''))?></textarea><?php else:?><input name="<?=$name?>" value="<?=htmlspecialchars((string)($editData[$name]??''))?>"><?php endif;?></label><?php endforeach;?><label>Aktiv<input type="checkbox" name="activ" value="1" <?=(!array_key_exists('activ',$editData)||(int)($editData['activ']??1)===1)?'checked':''?>></label></div><button><?=$editId>0?'Speichern':'Neu anlegen'?></button><?php if($editId>0):?> <a href="?entity=<?=$entity?>">Abbrechen</a><?php endif;?></form><h3>Vorhanden</h3><table><thead><tr><th>ID</th><?php foreach($entities[$entity]['fields'] as $label):?><th><?=htmlspecialchars($label)?></th><?php endforeach;?><th>Aktiv</th><th>Aktion</th></tr></thead><tbody><?php foreach($rows as $r):$d=(array)$r['data'];?><tr><td><?=(int)$r['id']?></td><?php foreach($entities[$entity]['fields'] as $name=>$label):?><td><?=htmlspecialchars((string)($d[$name]??''))?></td><?php endforeach;?><td><?=htmlspecialchars((string)($d['activ']??'1'))?></td><td><a href="?entity=<?=$entity?>&amp;edit=<?=(int)$r['id']?>">Bearbeiten</a> <form method="post" style="display:inline"><input type="hidden" name="record_id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="delete"><button class="danger">Deaktivieren</button></form></td></tr><?php endforeach;?></tbody></table></section><?php if(cal_auth_can('admin')):?><section class="card" id="users"><h2>Benutzer & Rollen</h2><form method="post"><input type="hidden" name="user_action" value="save"><input type="hidden" name="id" value="0"><div class="grid"><label>Benutzername<input name="username" required></label><label>E-Mail<input type="email" name="email"></label><label>Kennwort<input type="password" name="password" required></label><label>Rolle<select name="role"><option>viewer</option><option>editor</option><option>admin</option></select></label><label>Aktiv<input type="checkbox" name="active" value="1" checked></label></div><button>Benutzer anlegen</button></form><table><thead><tr><th>Benutzer</th><th>E-Mail</th><th>Rolle</th><th>Aktiv</th></tr></thead><tbody><?php foreach(cal_auth_users() as $u):?><tr><td><?=htmlspecialchars((string)$u['username'])?></td><td><?=htmlspecialchars((string)($u['email']??''))?></td><td><?=htmlspecialchars((string)$u['role'])?></td><td><?=!empty($u['active'])?'ja':'nein'?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?></main></body></html>
